/// Sets language, direction and labels.
pub fn set_language(app: &App, lang: Lang) {
    app.set_clip_clear_label(t(lang, "clip.clear").into());
    app.set_labels(labels(lang));
    app.set_rtl(lang.rtl());
}

pub fn apply_home(app: &App, view: &HomeView) {
    app.set_connected(true);
    app.set_score(i32::from(view.score));
    app.set_state(view.state.into());
    app.set_state_text(view.state_text.clone().into());
    let checks: Vec<CheckRow> = view
        .checks
        .iter()
        .map(|c| CheckRow {
            id: c.id.clone().into(),
            label: c.label.clone().into(),
            status: c.status.into(),
            status_text: c.status_text.clone().into(),
            freshness: c.freshness.clone().into(),
        })
        .collect();
    let actions: Vec<ActionCard> = view
        .actions
        .iter()
        .map(|a| ActionCard {
            id: a.id.clone().into(),
            title: a.title.clone().into(),
            detail: a.detail.clone().into(),
            button: a.button.clone().into(),
            priority: i32::from(a.priority),
        })
        .collect();
    let toggles: Vec<ToggleRow> = view
        .toggles
        .iter()
        .map(|t| ToggleRow {
            key: t.key.clone().into(),
            label: t.label.clone().into(),
            hint: t.hint.clone().into(),
            on: t.on,
            available: t.available,
        })
        .collect();
    app.set_checks(ModelRc::from(Rc::new(VecModel::from(checks))));
    app.set_actions(ModelRc::from(Rc::new(VecModel::from(actions))));
    app.set_toggles(ModelRc::from(Rc::new(VecModel::from(toggles))));
}

pub fn set_palette(app: &App, entries: &[PaletteEntry]) {
    let items: Vec<PaletteItem> = entries
        .iter()
        .map(|e| PaletteItem {
            id: e.id.clone().into(),
            title: e.title.clone().into(),
        })
        .collect();
    app.set_palette_items(ModelRc::from(Rc::new(VecModel::from(items))));
}

pub fn set_offline(app: &App) {
    app.set_connected(false);
    app.set_state("offline".into());
}

/// Seconds since 1970, for freshness text.
pub fn now_secs() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

pub fn set_ports(app: &App, rows: &[PortView], can_block: bool) {
    let items: Vec<PortRow> = rows
        .iter()
        .map(|r| PortRow {
            key: r.key.clone().into(),
            port: i32::from(r.port),
            title: r.title.clone().into(),
            detail: r.detail.clone().into(),
            fresh: r.fresh,
            blocked: r.blocked,
            exposed: r.exposed,
        })
        .collect();
    app.set_ports(ModelRc::from(Rc::new(VecModel::from(items))));
    app.set_can_block(can_block);
}

